import React, { Suspense } from 'react';
import { MemoryRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Provider } from 'react-redux';
import { store } from './store/store';
import { AppLayout } from './components/layout/AppLayout';
import { MemoryRouterSync } from './router/MemoryRouterSync';
import { isStandalone, showDevNav } from './dev/isStandalone';
import { StandaloneShell } from './standalone/StandaloneShell';
import { StandaloneMockNav } from './standalone/StandaloneMockNav';
import { StandaloneMockTopbar } from './standalone/StandaloneMockTopbar';
import { SimpleNotFoundPage } from '@linm-soft-org/linm-web-common-components';

const DevPageRoute = React.lazy(
  () => import(/* webpackChunkName: "dev" */ './dev/DevPageRoute'),
);
const GisDrawLivePage = React.lazy(
  () => import(/* webpackChunkName: "gis-draw-live-page" */ './pages/GisDrawLivePage'),
);
const GisPatrolMapPage = React.lazy(
  () => import(/* webpackChunkName: "gis-patrol-map-page" */ './pages/GisPatrolMapPage'),
);
const GisCameraMapPage = React.lazy(
  () => import(/* webpackChunkName: "gis-camera-map-page" */ './pages/GisCameraMapPage'),
);

const initialPath =
  typeof window !== 'undefined'
    ? window.location.pathname + window.location.search
    : '/';

/** Giữ `?type=` khi đổi `/gis/live` → `/gis/tai-san`. */
const RedirectToTaiSan: React.FC = () => {
  const loc = useLocation();
  return <Navigate to={`/gis/tai-san${loc.search}${loc.hash}`} replace />;
};

const AppShell: React.FC = () => (
  <StandaloneShell>
    <StandaloneMockNav />
    <StandaloneMockTopbar />
    <AppLayout />
  </StandaloneShell>
);

const Root: React.FC = () => (
  <Provider store={store}>
    <Router
      initialEntries={[initialPath]}
      future={{ v7_startTransition: true, v7_relativeSplatPath: true }}
    >
      <MemoryRouterSync />
      <Suspense fallback={<div>Đang tải…</div>}>
        <Routes>
        <Route path="/" element={isStandalone ? <AppShell /> : <AppLayout />}>
          {showDevNav && <Route path="dev" element={<DevPageRoute />} />}
          {showDevNav && (
            <Route index element={<Navigate to="/dev" replace />} />
          )}
          {!showDevNav && (
            <Route index element={<Navigate to="/gis/tai-san" replace />} />
          )}
          <Route path="gis" element={<RedirectToTaiSan />} />
          <Route path="gis/tai-san" element={<GisDrawLivePage />} />
          <Route path="gis/live" element={<RedirectToTaiSan />} />
          <Route path="gis/tuan-duong" element={<GisPatrolMapPage />} />
          <Route path="gis/camera" element={<GisCameraMapPage />} />
          <Route path="gis/ha-tang" element={<RedirectToTaiSan />} />
          <Route path="gis/tao-moi" element={<RedirectToTaiSan />} />
          <Route path="*" element={<SimpleNotFoundPage showDevNav={showDevNav} homePath="/gis/tai-san" />} />
        </Route>
      </Routes>
        </Suspense>
    </Router>
  </Provider>
);

export default Root;
