import { apiClient, unwrap } from '../api';
import type { BffResponse } from '../api';
import type { GisDto, GisPagedResult } from './responseModel';
import type { CreateGisRequest, UpdateGisRequest } from './requestModel';
import type {
  GisBasemapConfigDto,
  GisDrawingDto,
  GisGeoJsonFeatureCollection,
  GisGeoJsonQuery,
  GisHeatmapResponse,
  GisLayerDto,
  SaveGisDrawingRequest,
} from './mapModels';
import type { GisTypeSummaryResult } from './typeSummary';

/** Relative to VITE_API_URL (already includes /api/v1). */
const BASE = '/gis';

export const gisEndpoint = {
  getList: async (params?: {
    search?: string;
    page?: number;
    pageSize?: number;
  }) => {
    const qs = new URLSearchParams();
    if (params?.search) qs.set('search', params.search);
    qs.set('page', String(params?.page ?? 1));
    qs.set('pageSize', String(params?.pageSize ?? 20));
    const res = await apiClient.get<BffResponse<GisPagedResult>>(
      `${BASE}?${qs}`,
    );
    return unwrap(res);
  },

  getById: async (id: string) => {
    const res = await apiClient.get<BffResponse<GisDto>>(`${BASE}/${id}`);
    return unwrap(res);
  },

  create: async (data: CreateGisRequest) => {
    const res = await apiClient.post<BffResponse<GisDto>>(BASE, data);
    return unwrap(res);
  },

  update: async (id: string, data: UpdateGisRequest) => {
    const res = await apiClient.put<BffResponse<GisDto>>(
      `${BASE}/${id}`,
      data,
    );
    return unwrap(res);
  },

  delete: async (id: string): Promise<void> => {
    await apiClient.delete(`${BASE}/${id}`);
  },

  getLayers: async (purpose?: string) => {
    const qs = purpose ? `?purpose=${encodeURIComponent(purpose)}` : '';
    const res = await apiClient.get<BffResponse<GisLayerDto[]>>(`${BASE}/layers${qs}`);
    return unwrap(res);
  },

  getBasemapConfig: async (purpose?: string) => {
    const qs = purpose ? `?purpose=${encodeURIComponent(purpose)}` : '';
    const res = await apiClient.get<BffResponse<GisBasemapConfigDto>>(
      `${BASE}/basemap-config${qs}`,
    );
    return unwrap(res);
  },

  listDrawings: async (params?: { layerCode?: string; search?: string }) => {
    const qs = new URLSearchParams();
    if (params?.layerCode) qs.set('layerCode', params.layerCode);
    if (params?.search) qs.set('search', params.search);
    const q = qs.toString();
    const res = await apiClient.get<BffResponse<GisDrawingDto[]>>(
      `${BASE}/drawings${q ? `?${q}` : ''}`,
    );
    return unwrap(res);
  },

  createDrawing: async (data: SaveGisDrawingRequest) => {
    const res = await apiClient.post<BffResponse<GisDrawingDto>>(
      `${BASE}/drawings`,
      data,
    );
    return unwrap(res);
  },

  updateDrawing: async (id: string, data: SaveGisDrawingRequest) => {
    const res = await apiClient.put<BffResponse<GisDrawingDto>>(
      `${BASE}/drawings/${id}`,
      data,
    );
    return unwrap(res);
  },

  deleteDrawing: async (id: string): Promise<void> => {
    await apiClient.delete(`${BASE}/drawings/${id}`);
  },

  getGeoJson: async (layer: string, params?: GisGeoJsonQuery) => {
    const qs = new URLSearchParams();
    if (params?.bbox) qs.set('bbox', params.bbox);
    if (params?.pciMin != null) qs.set('pciMin', String(params.pciMin));
    if (params?.pciMax != null) qs.set('pciMax', String(params.pciMax));
    if (params?.search) qs.set('search', params.search);
    if (params?.route) qs.set('route', params.route);
    if (params?.lod) qs.set('lod', params.lod);
    if (params?.skip != null) qs.set('skip', String(params.skip));
    if (params?.take != null) qs.set('take', String(params.take));
    const q = qs.toString();
    const res = await apiClient.get<BffResponse<GisGeoJsonFeatureCollection>>(
      `${BASE}/geojson/${encodeURIComponent(layer)}${q ? `?${q}` : ''}`,
    );
    return unwrap(res);
  },

  getHeatmapPci: async (params?: {
    bbox?: string;
    pciMin?: number;
    pciMax?: number;
  }) => {
    const qs = new URLSearchParams();
    if (params?.bbox) qs.set('bbox', params.bbox);
    if (params?.pciMin != null) qs.set('pciMin', String(params.pciMin));
    if (params?.pciMax != null) qs.set('pciMax', String(params.pciMax));
    const q = qs.toString();
    const res = await apiClient.get<BffResponse<GisHeatmapResponse>>(
      `${BASE}/heatmap/pci${q ? `?${q}` : ''}`,
    );
    return unwrap(res);
  },

  getClusters: async (params?: {
    bbox?: string;
    zoom?: number;
    layer?: string;
  }): Promise<GisGeoJsonFeatureCollection> => {
    const qs = new URLSearchParams();
    if (params?.bbox) qs.set('bbox', params.bbox);
    if (params?.zoom != null) qs.set('zoom', String(Math.floor(params.zoom)));
    if (params?.layer) qs.set('layer', params.layer);
    const q = qs.toString();
    const res = await apiClient.get<BffResponse<GisGeoJsonFeatureCollection>>(
      `${BASE}/clusters${q ? `?${q}` : ''}`,
    );
    return unwrap(res);
  },

  getSummaryByType: async (): Promise<GisTypeSummaryResult> => {
    const res = await apiClient.get<BffResponse<GisTypeSummaryResult>>(
      `${BASE}/summary-by-type`,
    );
    return unwrap(res);
  },
};
