/**
 * Bind this MFE's `@linm/{mf}` name.
 * Prefer common `applyRuntimeApiUrl` when the pin exports it.
 * Fallback: `apiClient.setBaseURL` (common 1.43.0 dist chưa export helper).
 */
import * as LinmCommon from '@linm-soft-org/linm-web-common-components';
import { apiClient } from '@linm-soft-org/linm-web-common-components';

const LINM_MF_NAME = '@linm/rmms-gis';

type RuntimeApiHelpers = {
  applyRuntimeApiUrl?: (mfName: string, buildFallback?: string) => string;
  resolveRuntimeApiUrl?: (mfName: string, buildFallback?: string) => string;
};

type ApiClientWithBase = { setBaseURL?: (url: string) => void };

function stripSlash(url: string): string {
  return url.trim().replace(/\/$/, '');
}

function readManifestApiUrl(mfName: string): string {
  if (typeof window === 'undefined') return '';
  const fromMf =
    window.__LINM_MF_MANIFEST__?.microfrontends?.[mfName]?.env?.VITE_API_URL;
  return stripSlash(fromMf ?? '');
}

function resolveLocal(buildFallback?: string): string {
  const fromMf = readManifestApiUrl(LINM_MF_NAME);
  if (fromMf) return fromMf;
  return stripSlash(buildFallback ?? '');
}

const helpers = LinmCommon as unknown as RuntimeApiHelpers;

export function resolveRuntimeApiUrl(buildFallback?: string): string {
  if (typeof helpers.resolveRuntimeApiUrl === 'function') {
    return helpers.resolveRuntimeApiUrl(LINM_MF_NAME, buildFallback);
  }
  return resolveLocal(buildFallback);
}

const baked = import.meta.env.VITE_API_URL as string | undefined;
if (typeof helpers.applyRuntimeApiUrl === 'function') {
  helpers.applyRuntimeApiUrl(LINM_MF_NAME, baked);
} else {
  const url = resolveLocal(baked);
  const client = apiClient as unknown as ApiClientWithBase;
  if (url && typeof client.setBaseURL === 'function') {
    client.setBaseURL(url);
  }
}
