import React from 'react';
import { ErpAppLayout } from '@linm-soft-org/linm-web-common-components';
import { isStandalone } from '../../../dev/isStandalone';

/**
 * Shell layout — ErpAppLayout SSOT (SETUP-P2-22).
 * Standalone: flex-fill inside StandaloneShell (mock topbar owns chrome).
 * Embedded: fixed inset under Nav topbar / sidebar.
 */
export const AppLayout: React.FC = () => (
  <ErpAppLayout
    standalone={isStandalone}
    standaloneMode="flex-fill"
    variant="fixed"
    alwaysShowTopbar={false}
  />
);

export default AppLayout;
