import { useEffect } from 'react';

const SIDEBAR_SELECTOR = 'aside[aria-label="Điều hướng chính"]';
const SIDEBAR_LOGO_IMG = `${SIDEBAR_SELECTOR} > div:first-child img`;
const STYLE_ID = 'linm-standalone-sidebar-logo';

function escapeCssUrl(url: string): string {
  return url.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

/**
 * Override common Sidebar hardcoded brand PNG with RMMS `/icons` pack (SETUP-P2-24).
 * Expanded → logo-128 · collapsed rail → logo-64.
 */
export function useStandaloneSidebarLogo(collapsed: boolean): void {
  useEffect(() => {
    const iconUrl = collapsed ? '/icons/logo-64.png' : '/icons/logo-128.png';
    const escaped = escapeCssUrl(iconUrl);

    let style = document.getElementById(STYLE_ID) as HTMLStyleElement | null;
    if (!style) {
      style = document.createElement('style');
      style.id = STYLE_ID;
      document.head.appendChild(style);
    }
    style.textContent = `
      ${SIDEBAR_LOGO_IMG} {
        content: url('${escaped}') !important;
      }
    `;

    const apply = () => {
      document.querySelectorAll<HTMLImageElement>(SIDEBAR_LOGO_IMG).forEach((img) => {
        if (!img.src.endsWith(iconUrl)) {
          img.src = iconUrl;
        }
      });
    };

    apply();
    const timer = window.setTimeout(apply, 0);
    const observer = new MutationObserver(() => apply());
    observer.observe(document.body, { childList: true, subtree: true });

    return () => {
      window.clearTimeout(timer);
      observer.disconnect();
      document.getElementById(STYLE_ID)?.remove();
    };
  }, [collapsed]);
}
