import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import type { RootState } from '../store';
import type { GisDto } from '../../services/gis/responseModel';
import { gisService } from '../../services/gis/gisService';

interface GisFilters {
  search?: string;
  page: number;
  pageSize: number;
}

interface GisState {
  items: GisDto[];
  loading: boolean;
  pagination: { page: number; pageSize: number; totalCount: number };
  filters: GisFilters;
}

export const fetchGisItems = createAsyncThunk(
  'gis/fetchItems',
  async (_, { getState }) => {
    const { filters, pagination } = (getState() as RootState).gis;
    return await gisService.getList({
      ...filters,
      page: pagination.page,
      pageSize: pagination.pageSize,
    });
  },
);

const gisSlice = createSlice({
  name: 'gis',
  initialState: {
    items: [] as GisDto[],
    loading: false,
    pagination: { page: 1, pageSize: 20, totalCount: 0 },
    filters: { page: 1, pageSize: 20 } as GisFilters,
  } as GisState,
  reducers: {
    setFilters(state, { payload }: PayloadAction<Partial<GisFilters>>) {
      state.filters = { ...state.filters, ...payload };
      state.pagination.page = 1;
    },
    setPage(state, { payload }: PayloadAction<number>) {
      state.pagination.page = payload;
    },
  },
  extraReducers: (b) => {
    b.addCase(fetchGisItems.pending, (s) => {
      s.loading = true;
    })
      .addCase(fetchGisItems.fulfilled, (s, { payload }) => {
        s.loading = false;
        s.items = payload.items;
        s.pagination.totalCount = payload.totalCount;
      })
      .addCase(fetchGisItems.rejected, (s) => {
        s.loading = false;
      });
  },
});

export const { setFilters, setPage } = gisSlice.actions;
export default gisSlice.reducer;
