import { gisEndpoint } from './endpoint';
import type {
  GisGeoJsonFeature,
  GisGeoJsonFeatureCollection,
  GisGeoJsonQuery,
} from './mapModels';

export const GEOJSON_PAGE_SIZE = 100;
const MAX_PAGES = 20;
const TTL_MS = 10 * 60 * 1000;

export type GeoJsonPageParams = Omit<GisGeoJsonQuery, 'skip' | 'take'>;

type CacheEntry = { at: number; fc: GisGeoJsonFeatureCollection };

const memory = new Map<string, CacheEntry>();

function pageKey(layer: string, p: GeoJsonPageParams, skip: number): string {
  return ['land1', layer, p.bbox ?? '', p.search ?? '', p.route ?? '', p.lod ?? '', p.pciMin ?? '', p.pciMax ?? '', String(skip)].join('|');
}

function featureId(f: GisGeoJsonFeature): string {
  const p = f.properties || {};
  return String(f.id ?? p.id ?? p.code ?? JSON.stringify(f.geometry));
}

function fromCache(key: string): GisGeoJsonFeatureCollection | null {
  const hit = memory.get(key);
  if (hit && Date.now() - hit.at < TTL_MS) return hit.fc;
  try {
    const raw = sessionStorage.getItem(`gis-geo:${key}`);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as CacheEntry;
    if (typeof parsed?.at !== 'number' || Date.now() - parsed.at >= TTL_MS) return null;
    memory.set(key, parsed);
    return parsed.fc;
  } catch {
    return null;
  }
}

function toCache(key: string, fc: GisGeoJsonFeatureCollection): void {
  const entry: CacheEntry = { at: Date.now(), fc };
  memory.set(key, entry);
  try {
    sessionStorage.setItem(`gis-geo:${key}`, JSON.stringify(entry));
  } catch {
    /* quota */
  }
}

function pageHasMore(fc: GisGeoJsonFeatureCollection, got: number, loaded: number): boolean {
  if (got < GEOJSON_PAGE_SIZE) return false;
  if (loaded >= MAX_PAGES * GEOJSON_PAGE_SIZE) return false;
  const flag = Boolean(fc.hasMore);
  const total = fc.total ?? 0;
  if (total > 0 && loaded >= total) return false;
  return flag || (total > 0 && loaded < total) || got >= GEOJSON_PAGE_SIZE;
}

export async function loadGeoJsonBatched(
  layer: string,
  params?: GeoJsonPageParams,
  opts?: {
    signal?: AbortSignal;
    onPage?: (acc: GisGeoJsonFeatureCollection) => void;
    onBatch?: (acc: GisGeoJsonFeatureCollection) => void;
  },
): Promise<GisGeoJsonFeatureCollection> {
  const p = params ?? {};
  const merged: GisGeoJsonFeature[] = [];
  const seen = new Set<string>();
  let skip = 0;
  let total = 0;
  for (let i = 0; i < MAX_PAGES; i++) {
    if (opts?.signal?.aborted) break;
    const key = pageKey(layer, p, skip);
    let fc = fromCache(key);
    if (!fc) {
      const query: GisGeoJsonQuery = {
        ...p,
        skip,
        take: GEOJSON_PAGE_SIZE,
      };
      fc = await gisEndpoint.getGeoJson(layer, query);
      toCache(key, fc);
    }
    for (const f of fc.features ?? []) {
      const id = featureId(f);
      if (seen.has(id)) continue;
      seen.add(id);
      merged.push(f);
    }
    const pageTotal = fc.total ?? 0;
    if (pageTotal > 0) total = pageTotal;
    else if (total === 0) total = merged.length;
    const got = fc.features?.length ?? 0;
    const more = pageHasMore(fc, got, merged.length);
    const acc: GisGeoJsonFeatureCollection = {
      type: 'FeatureCollection',
      features: merged.slice(),
      total,
      skip,
      take: GEOJSON_PAGE_SIZE,
      hasMore: more,
    };
    (opts?.onPage ?? opts?.onBatch)?.(acc);
    if (!more) {
      acc.hasMore = false;
      return acc;
    }
    skip += GEOJSON_PAGE_SIZE;
  }
  return {
    type: 'FeatureCollection',
    features: merged,
    total,
    skip,
    take: GEOJSON_PAGE_SIZE,
    hasMore: false,
  };
}
