import { gisEndpoint } from './endpoint';
import { loadGeoJsonBatched } from './geoJsonBatchCache';
import type { GisGeoJsonFeatureCollection } from './mapModels';

export function getGisClusters(params?: {
  bbox?: string;
  zoom?: number;
  layer?: string;
}): Promise<GisGeoJsonFeatureCollection> {
  return gisEndpoint.getClusters(params);
}

export const gisService = {
  getList: (params?: Parameters<typeof gisEndpoint.getList>[0]) =>
    gisEndpoint.getList(params),
  getById: (id: string) => gisEndpoint.getById(id),
  create: (data: Parameters<typeof gisEndpoint.create>[0]) =>
    gisEndpoint.create(data),
  update: (
    id: string,
    data: Parameters<typeof gisEndpoint.update>[1],
  ) => gisEndpoint.update(id, data),
  delete: (id: string) => gisEndpoint.delete(id),
  getLayers: (purpose?: string) => gisEndpoint.getLayers(purpose),
  getBasemapConfig: (purpose?: string) => gisEndpoint.getBasemapConfig(purpose),
  listDrawings: (params?: Parameters<typeof gisEndpoint.listDrawings>[0]) =>
    gisEndpoint.listDrawings(params),
  createDrawing: (data: Parameters<typeof gisEndpoint.createDrawing>[0]) =>
    gisEndpoint.createDrawing(data),
  updateDrawing: (
    id: string,
    data: Parameters<typeof gisEndpoint.updateDrawing>[1],
  ) => gisEndpoint.updateDrawing(id, data),
  deleteDrawing: (id: string) => gisEndpoint.deleteDrawing(id),
  getGeoJson: (
    layer: string,
    params?: Parameters<typeof gisEndpoint.getGeoJson>[1],
  ) => gisEndpoint.getGeoJson(layer, params),
  loadGeoJsonBatched,
  getHeatmapPci: (params?: Parameters<typeof gisEndpoint.getHeatmapPci>[0]) =>
    gisEndpoint.getHeatmapPci(params),
  getClusters: getGisClusters,
  getSummaryByType: () => gisEndpoint.getSummaryByType(),
};
